 arch/riscv/net/bpf_jit_core.c   | 2 +-
 arch/x86/net/bpf_jit_comp.c     | 2 +-
 kernel/bpf/core.c               | 5 ++---
 6 files changed, 9 insertions(+), 8 deletions(-)

